class IndexDB{constructor(){this.dbName="SignMakerDB",this.dbVersion=2,this.storeName="customShields",this.templatesStoreName="templates",this.db=null,this.dbInitialized=this.init()}init(){return new Promise((e,t)=>{const r=indexedDB.open(this.dbName,this.dbVersion);r.onerror=e=>{console.error("IndexedDB error:",e.target.error),t(e.target.error)},r.onsuccess=t=>{this.db=t.target.result,console.log("IndexedDB connected successfully"),e(this.db)},r.onupgradeneeded=e=>{const t=e.target.result;t.objectStoreNames.contains(this.storeName)||t.createObjectStore(this.storeName,{keyPath:"fileName"}),t.objectStoreNames.contains(this.templatesStoreName)||t.createObjectStore(this.templatesStoreName,{keyPath:"id"})}})}async saveShield(e){
// Wait for DB initialization
return await this.dbInitialized,new Promise((t,r)=>{
// Convert file to base64
const s=new FileReader;s.readAsDataURL(e),s.onload=async()=>{const a={fileName:e.name,type:e.type,data:s.result,dateAdded:(new Date).toISOString()},o=this.db.transaction([this.storeName],"readwrite").objectStore(this.storeName).put(a);o.onsuccess=()=>t(a),o.onerror=()=>r(o.error)},s.onerror=e=>r(e)})}async getAllShields(){
// Wait for DB initialization
return await this.dbInitialized,new Promise((e,t)=>{const r=this.db.transaction([this.storeName],"readonly").objectStore(this.storeName).getAll();r.onsuccess=()=>e(r.result),r.onerror=()=>t(r.error)})}async deleteShield(e){
// Wait for DB initialization
return await this.dbInitialized,new Promise((t,r)=>{const s=this.db.transaction([this.storeName],"readwrite").objectStore(this.storeName).delete(e);s.onsuccess=()=>t(),s.onerror=()=>r(s.error)})}
// Template methods
async saveTemplate(e){return await this.dbInitialized,new Promise((t,r)=>{const s=(new Date).toISOString(),a={...e,id:e.id||Date.now().toString(),name:e.name,data:e.data,templateScope:e.templateScope||"panel",variants:Array.isArray(e.variants)?e.variants:[],dateCreated:e.dateCreated||s,dateModified:e.dateModified||s,dateLastUsed:e.dateLastUsed||null},o=this.db.transaction([this.templatesStoreName],"readwrite").objectStore(this.templatesStoreName).put(a);o.onsuccess=()=>t(a),o.onerror=()=>r(o.error)})}async updateTemplate(e,t){return this.saveTemplate({...t,id:e,dateModified:(new Date).toISOString()})}async getAllTemplates(){return await this.dbInitialized,new Promise((e,t)=>{const r=this.db.transaction([this.templatesStoreName],"readonly").objectStore(this.templatesStoreName).getAll();r.onsuccess=()=>e(r.result),r.onerror=()=>t(r.error)})}async getTemplate(e){return await this.dbInitialized,new Promise((t,r)=>{const s=this.db.transaction([this.templatesStoreName],"readonly").objectStore(this.templatesStoreName).get(e);s.onsuccess=()=>t(s.result),s.onerror=()=>r(s.error)})}async deleteTemplate(e){return await this.dbInitialized,new Promise((t,r)=>{const s=this.db.transaction([this.templatesStoreName],"readwrite").objectStore(this.templatesStoreName).delete(e);s.onsuccess=()=>t(),s.onerror=()=>r(s.error)})}}
